class Solution:
    def minimizeSum(self, nums: List[int]) -> int:
        import heapq
        small = heapq.nsmallest(3, nums)
        large = heapq.nlargest(3, nums)
        return min(large[0] - small[2], large[1] - small[1], large[2] - small[0])

